import { describe, expect, test } from "bun:test";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { JsonObject } from "../json.ts";
import { FakeHerdr } from "../mux/herdr/fixture.ts";
import { HerdrMux } from "../mux/herdr/adapter.ts";
import { serveOrganizationRoute } from "./organization.ts";
import { PlanStore } from "./plans.ts";
import { OperationStore } from "./operations.ts";

// SAFETY: response assertions below decode the bounded closed JSON bodies generated by the handler under test.
/* eslint-disable anti-slop/require-safety-comment-for-type-assertion */

const device = "d".repeat(64);
const actionRequest = (path: string, fields: JsonObject) => new Request(`https://collie${path}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(fields) });
function caller(mux: HerdrMux) {
  return { gate: () => null, pairedIdentity: () => device, audit: () => {}, resolve: async () => ({ host: "local", session: "primary", mux }) };
}

describe("scoped workspace and tab organization", () => {
  test("uses a fresh owner-bound plan, pre-removal ordering, and a durable one-shot receipt", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    expect(await mux.reachable()).toBe(true);
    const before = await mux.snapshot();
    const selected = before.spaces[0]!;
    const dir = await mkdtemp(join(tmpdir(), "collie-org-"));
    const stores = { plans: new PlanStore(), operations: new OperationStore(dir) };
    try {
      const path = `/api/workspace/${selected.spaceId}/move`;
      const intent = { insertIndex: before.spaces.length };
      const planResponse = await serveOrganizationRoute(actionRequest(`${path}/plan`, intent), new URL(`https://collie${path}/plan`), caller(mux), stores);
      expect(planResponse?.status).toBe(200);
      const plan = await planResponse!.json() as { planToken: string; effects: { focusChanges: boolean } };
      expect(plan.effects.focusChanges).toBe(false);
      const body = { ...intent, requestId: "org-move-1", planToken: plan.planToken };
      const applied = await serveOrganizationRoute(actionRequest(path, body), new URL(`https://collie${path}`), caller(mux), stores);
      expect(applied?.status).toBe(200);
      expect((await mux.snapshot()).spaces.map((row) => row.spaceId)).toEqual([before.spaces[1]!.spaceId, selected.spaceId]);
      const replay = await serveOrganizationRoute(actionRequest(path, body), new URL(`https://collie${path}`), caller(mux), stores);
      expect(replay?.status).toBe(200);
      expect((await mux.snapshot()).spaces.map((row) => row.spaceId)).toEqual([before.spaces[1]!.spaceId, selected.spaceId]);
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });

  test("workspace block reorder preserves the caller's selected order around an outside anchor", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    await mux.reachable();
    const initial = await mux.snapshot();
    await fake.createWorkspace({ cwd: "/tmp/third", label: "third" });
    const before = await mux.snapshot();
    const ids = [before.spaces[1]!.spaceId, before.spaces[2]!.spaceId];
    const anchor = before.spaces[0]!.spaceId;
    const route = "/api/workspaces/reorder";
    const payload = { workspaceIds: ids, beforeWorkspaceId: anchor };
    const stores = { plans: new PlanStore(), operations: new OperationStore() };
    const planned = await serveOrganizationRoute(actionRequest(`${route}/plan`, payload), new URL(`https://collie${route}/plan`), caller(mux), stores);
    expect(planned?.status).toBe(200);
    const token = (await planned!.json() as { planToken: string }).planToken;
    const moved = await serveOrganizationRoute(actionRequest(route, { ...payload, requestId: "org-block-1", planToken: token }), new URL(`https://collie${route}`), caller(mux), stores);
    expect(moved?.status).toBe(200);
    expect((await mux.snapshot()).spaces.map((space) => space.spaceId)).toEqual([ids[0]!, ids[1]!, anchor]);
    expect(initial.spaces.map((space) => space.spaceId)).toHaveLength(2);
  });

  test("rejects duplicate blocks, anchors inside the block, and stale topology before dispatch", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    await mux.reachable();
    const before = await mux.snapshot();
    const stores = { plans: new PlanStore(), operations: new OperationStore() };
    const route = "/api/workspaces/reorder";
    for (const [index, payload] of [
      { workspaceIds: [before.spaces[0]!.spaceId, before.spaces[0]!.spaceId], beforeWorkspaceId: null },
      { workspaceIds: [before.spaces[0]!.spaceId], beforeWorkspaceId: before.spaces[0]!.spaceId },
    ].entries()) {
      const invalid = await serveOrganizationRoute(actionRequest(`${route}/plan`, payload), new URL(`https://collie${route}/plan`), caller(mux), stores);
      expect(invalid?.status).toBe(index === 0 ? 400 : 409);
    }
    const selected = before.spaces[0]!;
    const movePath = `/api/workspace/${selected.spaceId}/move`;
    const action = { insertIndex: 0 };
    const planResponse = await serveOrganizationRoute(actionRequest(`${movePath}/plan`, action), new URL(`https://collie${movePath}/plan`), caller(mux), stores);
    const plan = await planResponse!.json() as { planToken: string };
    await fake.moveWorkspace(selected.spaceId, before.spaces.length);
    const writesBefore = fake.writes().length;
    const stale = await serveOrganizationRoute(actionRequest(movePath, { ...action, planToken: plan.planToken, requestId: "org-stale-1" }), new URL(`https://collie${movePath}`), caller(mux), stores);
    expect(stale?.status).toBe(409);
    expect(fake.writes()).toHaveLength(writesBefore);
  });

  test("tab move is bounded to its existing workspace and focus only follows explicit focus routes", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    await mux.reachable();
    const snapshot = await mux.snapshot();
    const tab = snapshot.tabs[0]!;
    const stores = { plans: new PlanStore(), operations: new OperationStore() };
    const movePath = `/api/tab/${tab.tabId}/move`;
    const badIndex = await serveOrganizationRoute(actionRequest(`${movePath}/plan`, { insertIndex: 99 }), new URL(`https://collie${movePath}/plan`), caller(mux), stores);
    expect(badIndex?.status).toBe(409);
    const renamePath = `/api/workspace/${snapshot.spaces[0]!.spaceId}/rename`;
    const renamePlan = await serveOrganizationRoute(actionRequest(`${renamePath}/plan`, { label: "Renamed" }), new URL(`https://collie${renamePath}/plan`), caller(mux), stores);
    expect(renamePlan?.status).toBe(200);
    expect((await mux.snapshot()).spaces.find((space) => space.spaceId === snapshot.spaces[0]!.spaceId)?.focused).toBe(snapshot.spaces[0]!.focused);
    const crossWorkspace = await serveOrganizationRoute(actionRequest(movePath, { insertIndex: 0, requestId: "cross-1", planToken: "not-a-plan", destinationWorkspaceId: snapshot.spaces[1]!.spaceId }), new URL(`https://collie${movePath}`), caller(mux), stores);
    expect(crossWorkspace?.status).toBe(400);
  });

  test("tab move uses the pre-removal index and preserves the tab's stable number", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    await mux.reachable();
    const initial = await mux.snapshot();
    const workspaceId = initial.spaces[0]!.spaceId;
    await fake.createTab(workspaceId, { label: "second" });
    const before = await mux.snapshot();
    const siblings = before.tabs.filter((tab) => tab.spaceId === workspaceId);
    const selected = siblings[0]!;
    const route = `/api/tab/${selected.tabId}/move`;
    const stores = { plans: new PlanStore(), operations: new OperationStore() };
    const planResponse = await serveOrganizationRoute(actionRequest(`${route}/plan`, { insertIndex: 2 }), new URL(`https://collie${route}/plan`), caller(mux), stores);
    expect(planResponse?.status).toBe(200);
    const plan = await planResponse!.json() as { planToken: string };
    const moved = await serveOrganizationRoute(actionRequest(route, { insertIndex: 2, requestId: "tab-move-2", planToken: plan.planToken }), new URL(`https://collie${route}`), caller(mux), stores);
    expect(moved?.status).toBe(200);
    const after = (await mux.snapshot()).tabs.filter((tab) => tab.spaceId === workspaceId);
    expect(after.map((tab) => tab.tabId)).toEqual([siblings[1]!.tabId, selected.tabId]);
    expect(after.map((tab) => tab.number)).toEqual([siblings[1]!.number, siblings[0]!.number]);
  });

  test("rechecks write authority and paired identity at mux dispatch admission", async () => {
    for (const mode of ["gate", "identity"] as const) {
      const fake = new FakeHerdr();
      const mux = new HerdrMux(fake, () => []);
      await mux.reachable();
      const workspaceId = (await mux.snapshot()).spaces[0]!.spaceId;
      const route = `/api/workspace/${workspaceId}/focus`;
      const stores = { plans: new PlanStore(), operations: new OperationStore() };
      const payload = {};
      const planned = await serveOrganizationRoute(actionRequest(`${route}/plan`, payload), new URL(`https://collie${route}/plan`), caller(mux), stores);
      const planToken = (await planned!.json() as { planToken: string }).planToken;
      let gates = 0;
      let identities = 0;
      const delayedCaller = {
        gate: () => ++gates === 1 || mode !== "gate" ? null : new Response("revoked", { status: 403 }),
        pairedIdentity: () => ++identities === 1 || mode !== "identity" ? device : "e".repeat(64),
        audit: () => {},
        resolve: async () => ({ host: "local", session: "primary", mux }),
      };
      const before = fake.writes().length;
      const result = await serveOrganizationRoute(actionRequest(route, { ...payload, requestId: `late-${mode}`, planToken }), new URL(`https://collie${route}`), delayedCaller, stores);
      expect(result?.status).toBe(409);
      expect(fake.writes()).toHaveLength(before);
    }
  });

  test("legacy one-step tab rename and close requests remain available to the existing handler", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    await mux.reachable();
    const tabId = (await mux.snapshot()).tabs[0]!.tabId;
    const stores = { plans: new PlanStore(), operations: new OperationStore() };
    for (const [path, fields] of [
      [`/api/tab/${tabId}/rename`, { label: "Legacy rename" }],
      [`/api/tab/${tabId}/close`, {}],
    ] as const) {
      const request = actionRequest(path, fields);
      expect(await serveOrganizationRoute(request, new URL(`https://collie${path}`), caller(mux), stores)).toBeNull();
      expect(await request.json()).toEqual(fields);
    }
  });

  test("group-close plan names every linked workspace and pane, and vendor refusal is not treated as a transport loss", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    await mux.reachable();
    const root = { spaceId: "w1" };
    const repoRoot = "/home/dev/collie";
    const linkedId = await fake.addWorktreeGroup(root.spaceId, repoRoot);
    const snapshot = await mux.snapshot();
    const stores = { plans: new PlanStore(), operations: new OperationStore() };
    const closePath = `/api/workspace/${root.spaceId}/close`;
    const groupDiscovery = await serveOrganizationRoute(actionRequest(`${closePath}/plan`, { closeGroup: false }), new URL(`https://collie${closePath}/plan`), caller(mux), stores);
    expect(groupDiscovery?.status).toBe(200);
    const preview = await groupDiscovery!.json() as { effects: { groupCloseRequired: boolean; groupPreviewIds: string[]; deletesCheckouts: boolean } };
    expect(preview.effects).toMatchObject({ groupCloseRequired: true, groupPreviewIds: [root.spaceId, linkedId], deletesCheckouts: false });
    expect(snapshot.panes.filter((pane) => pane.spaceId === root.spaceId || pane.spaceId === linkedId)).toHaveLength(3);
    const onePlan = await serveOrganizationRoute(actionRequest(`${closePath}/plan`, { closeGroup: false }), new URL(`https://collie${closePath}/plan`), caller(mux), stores);
    const oneToken = (await onePlan!.json() as { planToken: string }).planToken;
    const refused = await serveOrganizationRoute(actionRequest(closePath, { closeGroup: false, requestId: "org-close-one", planToken: oneToken }), new URL(`https://collie${closePath}`), caller(mux), stores);
    expect(refused?.status).toBe(409);
    const groupPlan = await serveOrganizationRoute(actionRequest(`${closePath}/plan`, { closeGroup: true }), new URL(`https://collie${closePath}/plan`), caller(mux), stores);
    const groupToken = (await groupPlan!.json() as { planToken: string }).planToken;
    const closed = await serveOrganizationRoute(actionRequest(closePath, { closeGroup: true, requestId: "org-close-group", planToken: groupToken }), new URL(`https://collie${closePath}`), caller(mux), stores);
    expect(closed?.status).toBe(200);
    expect((await mux.snapshot()).spaces.some((space) => space.spaceId === linkedId || space.spaceId === root.spaceId)).toBe(false);
    expect(await fake.listWorktrees(repoRoot)).toHaveLength(2);
  });

  test("a worktree added after group review invalidates the old group-close plan", async () => {
    const fake = new FakeHerdr();
    const mux = new HerdrMux(fake, () => []);
    await mux.reachable();
    const rootId = "w1";
    const repoRoot = "/home/dev/reviewed-group";
    const firstLinked = await fake.addWorktreeGroup(rootId, repoRoot);
    const stores = { plans: new PlanStore(), operations: new OperationStore() };
    const route = `/api/workspace/${rootId}/close`;
    const planResponse = await serveOrganizationRoute(actionRequest(`${route}/plan`, { closeGroup: true }), new URL(`https://collie${route}/plan`), caller(mux), stores);
    expect(planResponse?.status).toBe(200);
    const plan = await planResponse!.json() as { planToken: string; effects: { groupPreviewIds: string[] } };
    expect(plan.effects.groupPreviewIds).toEqual([rootId, firstLinked]);

    const secondLinked = await fake.addWorktreeGroup(rootId, repoRoot);
    const writesBefore = fake.writes().length;
    const stale = await serveOrganizationRoute(actionRequest(route, {
      closeGroup: true,
      requestId: "stale-group-close",
      planToken: plan.planToken,
    }), new URL(`https://collie${route}`), caller(mux), stores);

    expect(stale?.status).toBe(409);
    expect(fake.writes()).toHaveLength(writesBefore);
    const current = await mux.snapshot();
    expect(current.spaces.map((space) => space.spaceId)).toContain(rootId);
    expect(current.spaces.map((space) => space.spaceId)).toContain(firstLinked);
    expect(current.spaces.map((space) => space.spaceId)).toContain(secondLinked);
  });
});
/* eslint-enable anti-slop/require-safety-comment-for-type-assertion */
